 if(recipe){if(recipe.floorSignatures&&recipe.backgroundHashes.some((hash,i)=>Math.floor(i/r.w)>=recipe.wallRows&&!recipe.floorSignatures.includes(hash)))throw Error('The background repair contains non-floor artwork. Choose a clean floor sample.');const hashes=new Map();for(let id=0;id<map.rom.attributes.length;id++){const hash=pixelSignature(nativeAtlasTile(atlas,id));if(!hashes.has(hash))hashes.set(hash,id);}const ids=recipe.backgroundHashes.map(h=>hashes.get(h));if(ids.every(Number.isInteger)){const cells=ids.map((id,i)=>atlasPatchCell(map,id,{mode:Math.floor(i/r.w)<recipe.wallRows?'block':'walk',collision:Math.floor(i/r.w)<recipe.wallRows?1:0,elevation:3}));return{cells,confidence:cells.map(()=> 'reviewed continuous surface'),generated:[],structuralRepair:true};}}
