 for(let y=0;y<map.height;y++)for(let x=0;x<map.width;x++){if(inside(r,x,y)||excluded.some(o=>inside(o,x,y)))continue;const t=map.layers.ground[y*map.width+x];if(!t||![map.rom.atlasId,...map.rom.layerAtlasIds].includes(t.a))continue;const id=t.sy/16*16+t.sx/16;if(!refs.has(id))refs.set(id,[]);refs.get(id).push({x,y,rule:map.movement?.[y*map.width+x]||nativeCellRule(map,x,y)});}
 for(let id=0;id<map.rom.attributes.length;id++){if(occupied.has(id))continue;const pixels=nativeAtlasTile(atlas,id),colours=new Set();for(let i=0;i<pixels.length;i+=4)colours.add(rgb(pixels,i));const behavior=map.rom.attributes[id]&(map.rom.engine==='frlg'?511:255);if(![0,2].includes(behavior))continue;tiles.push({id,pixels,colours,novel:[...colours].filter(c=>!knownColours.has(c)).length,refs:refs.get(id)||[]});}
