   if(parts.length===4){if(!atlas.layers)planePixels[0].set(pixels);let hash=2166136261;for(const plane of planePixels)for(const v of plane)hash=Math.imul(hash^v,16777619);const id='recovery-floor-'+map.rom.sourceId.slice(0,12)+'-'+(hash>>>0).toString(16);planePixels.forEach((pixels,l)=>{if(!generated.some(a=>a.id===id+'-'+l))generated.push({id:id+'-'+l,width:16,height:16,pixels});});const floor=parts.map(p=>p.tile).find(t=>t.refs.some(p=>p.rule&&!p.rule.collision))||parts[0].tile,rule=floor.refs.find(p=>p.rule&&!p.rule.collision)?.rule||map.rom.tileDefaults?.[floor.id]||{mode:'walk',collision:0,elevation:3,behavior:0,layerType:1};cells.push({layers:{ground:{a:id+'-0',sx:0,sy:0,size:16,renderRole:'ground'},details:{a:id+'-1',sx:0,sy:0,size:16,renderRole:'behind'},objects:null,overhead:planePixels[2]?{a:id+'-2',sx:0,sy:0,size:16,renderRole:'foreground'}:null},rule:{...copy(rule),exactArtwork:true,reuseNativeComposite:true}});confidence.push(masked?'native pixel repair':'native quarter repair');continue;}
   cells.push(null);confidence.push('paint');continue;
