export function patchBackgroundChanges({r,image,mask,patchPixels}){let changed=0;for(let y=0;y<r.h*16;y++)for(let x=0;x<r.w*16;x++){const j=(y*r.w*16+x)*4;if(mask[j+3])continue;const i=((r.y*16+y)*image.width+r.x*16+x)*4;if(image.pixels[i]!==patchPixels[j]||image.pixels[i+1]!==patchPixels[j+1]||image.pixels[i+2]!==patchPixels[j+2]||image.pixels[i+3]!==patchPixels[j+3])changed++;}return changed;}
